/**
 * VFS-FS: High-performance OPFS-based Node.js fs polyfill
 *
 * Uses SharedArrayBuffer + Atomics for sync operations with a VFS binary format.
 *
 * @example
 * ```typescript
 * import fs from '@componentor/fs';
 *
 * // Sync API (blocks until ready)
 * fs.writeFileSync('/hello.txt', 'Hello World!');
 * const data = fs.readFileSync('/hello.txt', 'utf8');
 *
 * // Async API
 * await fs.promises.writeFile('/async.txt', 'Async data');
 * const content = await fs.promises.readFile('/async.txt', 'utf8');
 * ```
 */

export { VFSFileSystem, disposeAll } from './filesystem.js';
// Fairness ticket lock over the control SAB — exported so a host that shares one
// control SAB across several raw sync clients (e.g. multiple Web Workers) can
// serialize them with the SAME lock the library's own `syncRequest` uses.
export { acquireFsLock, releaseFsLock } from './protocol/fs-lock.js';
export { SAB_OFFSETS, SIGNAL } from './protocol/opcodes.js';
export { createServiceWorkerBridge } from './sw-bridge.js';
export type { ServiceWorkerBridgeOptions } from './sw-bridge.js';
export { NodeReadable, NodeWritable, SimpleEventEmitter } from './node-streams.js';
export { NodeReadable as ReadStream, NodeWritable as WriteStream } from './node-streams.js';
export { constants } from './constants.js';
// The result classes, exported as node exports them so `instanceof` type-tests work.
export { Stats, BigIntStats, Dirent } from './stats-classes.js';
export { Dir } from './dir.js';
export { FSError, createError, statusToError } from './errors.js';
export { unpackToOPFS, loadFromOPFS, repairVFS } from './helpers.js';
export type { UnpackResult, LoadResult, RepairResult } from './helpers.js';
export * as path from './path.js';
export type {
  OpendirOptions,
  StatFs,
  StatOptions,
  ReadOptions,
  WriteOptions,
  MkdirOptions,
  RmdirOptions,
  RmOptions,
  CpOptions,
  ReaddirOptions,
  Encoding,
  PathLike,
  FileHandle,
  VFSConfig,
  VFSLimits,
  FSMode,
  WatchOptions,
  WatchEventType,
  FSWatcher,
  WatchListener,
  WatchFileListener,
  ReadStreamOptions,
  WriteStreamOptions,
  FSReadStream,
  FSWriteStream,
  OpenAsBlobOptions,
} from './types.js';

// Multi-drive abstraction (additive; the single-OPFS API above is unchanged). See drives/DESIGN.md.
export * from './drives/index.js';

import { VFSFileSystem } from './filesystem.js';

/** Create a configured VFS instance */
export function createFS(config?: import('./types.js').VFSConfig): VFSFileSystem {
  return new VFSFileSystem(config);
}

// Lazy default singleton — only created on first access
let _defaultFS: VFSFileSystem | undefined;

/** Get (or create) the default VFS singleton */
export function getDefaultFS(): VFSFileSystem {
  if (!_defaultFS) _defaultFS = new VFSFileSystem();
  return _defaultFS;
}

/** Async init helper — avoids blocking main thread */
export function init(): Promise<void> {
  return getDefaultFS().init();
}
